{"entry_id": 981057, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "[رأم] رَئِمَتِ الناقةُ ولدَها رِئْماناً، إذا أحبَّتْهُ. ويقال للبوّ والولد رَأْمٌ. والناقةُ رَءُومٌ ورائمَةٌ. وأرْأَمْنا الناقة: عطفناها على الرأم. وقال الاموى: الرءوم من الشاء: التى تلحس ثياب من مربه", "translation_en": null, "domain": null, "dict": "تاج اللغة وصِحاح العربية للجوهري", "source_type": "hawramani"}
{"entry_id": 986442, "headword": "رَأَمَ ", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "(رَأَمَ) الرَّاءُ وَالْهَمْزَةُ وَالْمِيمُ أَصْلٌ يَدُلُّ عَلَى مُضَامَّةٍ وَقُرْبٍ وَعَطْفٍ. يُقَالُ لِكُلِّ مَنْ أَحَبَّ شَيْئًا وَأَلِفَهُ: قَدْ رَئِمَهُ. وَأَصْلُهُ مِنْ قَوْلِهِمْ: رَأَمَ الْجُرْ", "translation_en": null, "domain": null, "dict": "مقاييس اللغة لابن فارس", "source_type": "hawramani"}
{"entry_id": 991822, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "[ر أم] رَئِمَت النّاقَةُ وَلَدَها رَأْمًا ورِئْمانًا عَطَفَتْ عليهِ ولَزِمَتْهُ قال\n(أَمْ كَيْفَ ينفع ما تُعْطِي العَلُوقُ ... رِئْمانُ أَنْفٍ إذا ما ضُنَّ باللَّبَنِ)\nويُرْوَى رِئْمانَ ورئمانُ ورِئما", "translation_en": null, "domain": null, "dict": "المحكم والمحيط الأعظم لابن سيده الأندلسي", "source_type": "hawramani"}
{"entry_id": 997602, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "ر أ م\nرئمت الناقة الولد أو البوّ رأما ورئماناً، وناقة رائمة ورائم ورءوم، ونوق روائم. وأما لناقتكم رأم أي شيء ترأمه من بوّ أو ولد ناقة أخرى. وأرأمنا الناقة ولدها: عطفناها عليه، وترأمت عليه: أرزمت وحنت.", "translation_en": null, "domain": null, "dict": "أساس البلاغة للزمخشري", "source_type": "hawramani"}
{"entry_id": 776868, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "(رأم) - وفي حديث عَائِشَةَ، رَضِى الله عنها، \"تَرْأَمُه ويَأْباها\" . : أي تَعطِف عليه كما تَرأَمُ الأُمُّ ولدَها، والناقَةُ حُوارَها. وناقة رَؤُومٌ ورَائِمَةٌ، وكُلُّ مَنْ أحبَّ شيئًا وأَلِفَه فقد رَئ", "translation_en": null, "domain": null, "dict": "المجموع المغيث في غريبي القرآن والحديث لأبو موسى المديني", "source_type": "hawramani"}
{"entry_id": 779944, "headword": "رَأَمَ", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "(رَأَمَ)(س) فِي حَدِيثِ عَائِشَةَ تَصفُ عُمَرَ «تَرْأَمُهُ ويأْباها» تُريد الدُّنْيَا: أَيْ تَعْطِف عَلَيْهِ كَمَا تَرْأَمُ الأمُّ ولَدها والنَّاقَةُ حُوَارَها فتشُمُّه وتَتَرَشَّفه، وكُلّ مَنْ أحبَّ ", "translation_en": null, "domain": null, "dict": "النهاية في غريب الحديث والأثر لأبي السعادات ابن الأثير الجزري", "source_type": "hawramani"}
{"entry_id": 973373, "headword": "رَأمٌ", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "رَأمٌ:\nمهموز ويخفف، والرأم في الأصل البوّ أو ولد ظأرت عليه غير أمّه، قال بعضهم:\nكأمّهات الرأم أو مطافلا\nوهو جبل باليمامة تقطع منه الأرحاء، قال الشاعر:\nكأن حفيف الخصيتين على استها ... حفيف رحى راميّة ض", "translation_en": null, "domain": null, "dict": "معجم البلدان لياقوت الحموي", "source_type": "hawramani"}
{"entry_id": 787592, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "ر أ م: (الْأَرْآمُ) الظِّبَاءُ الْبِيضُ الْخَالِصَةُ الْبَيَاضِ وَاحِدُهَا (رِئْمٌ) وَهِيَ تَسْكُنُ الرَّمْلَ.", "translation_en": null, "domain": null, "dict": "مختار الصحاح للرازي", "source_type": "hawramani"}
{"entry_id": 769772, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "رأم: رَئِمتِ الناقةُ ولدها تَرْأَمُهُ رَأْماً ورَأَماناً: عطفتْ عليه\nولزمته، وفي التهذيب: رِئْماناً أَحَبَّتْهُ؛ قال:\nأَم كيف يَنْفَعُ ما تُعْطي العَلُوقُ به\nرئْمانُ أَنْفٍ، إِذا ما ضُنَّ باللبن؟\nويرو", "translation_en": null, "domain": null, "dict": "لسان العرب لابن منظور", "source_type": "hawramani"}
{"entry_id": 809487, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "[رأم] في ح عائشة في عمر \"ترأمه\" ويأباها، أي الدنيا تعطف عليه كما ترأم الأم ولدها والناقة حوارها فتشمه، من رئمه إذا أحبه وألفه.", "translation_en": null, "domain": null, "dict": "مجمع بحار الأنوار للفَتِّنيّ", "source_type": "hawramani"}
{"entry_id": 825617, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "رأم(} رَئِم الشَّيءَ، كَسَمِع: أحبَّه وَأَلِفَه) ولَزِمَه، نَقله الجوهَرِيُّ، وَهُوَ مجَاز، وَمِنْه قَوْلُ عُبَيْدِ اللهِ بنِ عَبْدِ الله بنِ عُتْبَةَ:(أَبي اللهُ والإِسلامُ أَن {تَرْأَم الخَنَى ... ن", "translation_en": null, "domain": null, "dict": "تاج العروس لمرتضى الزبيدي", "source_type": "hawramani"}
{"entry_id": 952351, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "ر\nأم1 رَئِمَتْ وَلَدَهَا, (T, S, M, K,) aor. ـَ (T,) inf. n. رِئْمَانٌ, (T, S, M, K *) and رَأْمٌ (M, K *) and رَأَمَانٌ, (TA,) She (a camel) loved, (T, S,) or affected, or inclined to, and kept to, o", "translation_en": null, "domain": null, "dict": "المعجم العربي الإنجليزي لإدوارد وليام لين", "source_type": "hawramani"}
{"entry_id": 844267, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "رأم: رَئِمَ: أَلِف، اعتاد (المقدمة 1: 255، 256).\nرِئْم: وصف كولومب (ص43) هذا الحيوان، كما وصفه دوماس في مجلة الشرق والجزائر (13: 163) وعليك تبدل rinne ب rime.\nرِئم: ظبي (ألكالا).\nرئم: كركدن، وحيد القر", "translation_en": null, "domain": null, "dict": "تكملة المعاجم العربية لرينهارت دوزي", "source_type": "hawramani"}
{"entry_id": 894459, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "(رأم)الْإِنَاء رأما لامه وَأَصْلحهُ وَالْحَبل فتله فَتلا شَدِيدا", "translation_en": null, "domain": null, "dict": "المعجم الوسيط لمجموعة من المؤلفين", "source_type": "hawramani"}
{"entry_id": 894535, "headword": "رام", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "(رام)الْجرْح ريما وريمانا انْضَمَّ فَمه للبرء وَالْحمل مَال وَعَلِيهِ ريما فضل وَزَاد يُقَال لَهُ ريم على هَذَا ومكانه وَفُلَانًا وَمن عِنْده برحه يُقَال مَا رام مَكَانَهُ وَمَا رام من مَكَانَهُ مَا ف", "translation_en": null, "domain": null, "dict": "المعجم الوسيط لمجموعة من المؤلفين", "source_type": "hawramani"}
{"entry_id": 858348, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "رأمرئِمَ يَرأَم، رَأْمًا ورَأَمانًا، فهو رائم ورَءُوم، والمفعول مَرْءوم (للمتعدِّي)• رئِم الجُرْحُ: التأم.• رئِمتِ الأنثى ولدَها: أحبّته ولزمته وعطفت عليه \"أم رءوم- قلب رءوم لا يعرف القسوة\". \nرَأْم [م", "translation_en": null, "domain": null, "dict": "معجم اللغة العربية المعاصرة لأحمد مختار عمر", "source_type": "hawramani"}
{"entry_id": 904737, "headword": "رأم", "headword_norm": "رام", "root": "رم", "pos": null, "definitions_text": "رأم: الرَّأْمُ: البَوُّ. ووَلَدٌ تُعْطَفُ عليه غَيْرُ أُمِّه، ورَئمَتْه النَّاقَةُ رِئْمَاناً، وأرْأمْنَاها: عَطَفْناها على رَأْمٍ، وناقَةٌ رَؤُوْمٌ ورَائِمَةٌ.\nوكُلُّ مَنْ أحَبَّ شَيْئاً وأَلِفَه: فق", "translation_en": null, "domain": null, "dict": "المحيط في اللغة للصاحب بن عباد", "source_type": "hawramani"}
{"entry_id": 99902, "headword": "رَأْم", "headword_norm": "رام", "root": "رأم", "pos": "noun", "definitions_text": "البو (جلد الحوار يحشى لتعطف عليه الناقة) الظباء البيض (واحدها رئم) الأثافي التي رئمت الرماد", "translation_en": null, "domain": null, "dict": "كتاب العين", "source_type": "ocr"}
